/bin/bash -lc "python - <<'PY'
import json, urllib.request
for page in range(1,4):
    url=f'https://quay.io/api/v1/repository/biocontainers/ete3/tag/?limit=100&page={page}&onlyActiveTags=true'
    with urllib.request.urlopen(url,timeout=30) as fh: obj=json.load(fh)
    for t in obj.get('tags',[]):
        n=t['name']
        if n.startswith(('3.1.3','3.1.2')): print(n)
    if not obj.get('has_additional'): break
PY"

